16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: '+' followed by 8 to 15 digits")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
61	    private Set<Pet> pets;
62	
63	    /**
64	     * Default the registration date to the server's current date when none was
65	     * supplied. Runs only on insert, so an explicitly provided date is kept.
66	     */
67	    @PrePersist
68	    private void defaultRegistrationDate() {
69	        if (this.registrationDate == null) {
70	            this.registrationDate = LocalDate.now();
71	        }
72	    }
73	
74	    public String getAddress() {
75	        return this.address;
76	    }
77	
78	    public void setAddress(String address) {
79	        this.address = address;
80	    }
81	
82	    public String getCity() {
83	        return this.city;
84	    }
85	
86	    public void setCity(String city) {
87	        this.city = city;
88	    }
89	
90	    public String getTelephone() {
91	        return this.telephone;
92	    }
93	
94	    public void setTelephone(String telephone) {
95	        this.telephone = telephone;
96	    }
97	
98	    public String getEmail() {
99	        return this.email;
100	    }
101	
102	    public void setEmail(String email) {
103	        this.email = email;
104	    }
105	
106	    public LocalDate getRegistrationDate() {
107	        return this.registrationDate;
108	    }
109	
110	    public void setRegistrationDate(LocalDate registrationDate) {
111	        this.registrationDate = registrationDate;
112	    }
113	
114	    public String getCustomerCode() {
115	        return this.customerCode;
116	    }
117	
118	    public void setCustomerCode(String customerCode) {
119	        this.customerCode = customerCode;
120	    }
121	
122	    /**
123	     * Return this owner's name formatted as {@code LastName, FirstName}.
124	     */
125	    @Transient
126	    public String getDisplayName() {
127	        return this.getLastName() + ", " + this.getFirstName();
128	    }
129	
130	    protected Set<Pet> getPetsInternal() {
131	        if (this.pets == null) {
132	            this.pets = new HashSet<>();
133	        }
134	        return this.pets;
135	    }
136	
137	    protected void setPetsInternal(Set<Pet> pets) {
138	        this.pets = pets;
139	    }
140	
141	    public List<Pet> getPets() {
142	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
143	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
144	        return Collections.unmodifiableList(sortedPets);
145	    }
146	
147	    public void setPets(List<Pet> pets) {
148	        this.pets = new HashSet<>(pets);
149	    }
150	
151	    public void addPet(Pet pet) {
152	        getPetsInternal().add(pet);
153	        pet.setOwner(this);
154	    }
155	
156	    /**
157	     * Return the Pet with the given name, or null if none found for this Owner.
158	     *
159	     * @param name to test
160	     * @return true if pet name is already in use
161	     */
162	    public Pet getPet(String name) {
163	        return getPet(name, false);
164	    }
165	
166	    /**
167	     * Return the Pet with the given name, or null if none found for this Owner.
168	     *
169	     * @param name to test
170	     * @return true if pet name is already in use
171	     */
172	    public Pet getPet(String name, boolean ignoreNew) {
173	        name = name.toLowerCase();
174	        for (Pet pet : getPetsInternal()) {
175	            if (!ignoreNew || !pet.isNew()) {
176	                String compName = pet.getName();
177	                compName = compName.toLowerCase();
178	                if (compName.equals(name)) {
179	                    return pet;
180	                }
181	            }
182	        }
183	        return null;
184	    }
185	
186	    public Pet getPet(Integer petId) {
187	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
188	    }
189	
190	    @Override
191	    public String toString() {
192	        return new ToStringCreator(this)
193	
194	            .append("id", this.getId())
195	            .append("new", this.isNew())
196	            .append("lastName", this.getLastName())
197	            .append("firstName", this.getFirstName())
198	            .append("address", this.address)
199	            .append("city", this.city)
200	            .append("telephone", this.telephone)
201	            .append("email", this.email)
202	            .toString();
203	    }
204	}
