17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import java.util.ArrayList;
20	import java.util.List;
21	
22	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
23	
24	/**
25	 * Validates that an {@link OwnerFieldsDto} carries a non-blank value for every
26	 * required owner field. This complements the schema-level Bean Validation
27	 * constraints: {@code address} and {@code city} have no pattern, so a
28	 * whitespace-only value would otherwise satisfy their {@code @Size(min = 1)}
29	 * constraint and slip through.
30	 */
31	public final class OwnerFieldsValidator {
32	
33	    private OwnerFieldsValidator() {
34	    }
35	
36	    /**
37	     * Rejects an owner whose required fields are missing or blank.
38	     *
39	     * @param ownerFields the submitted owner fields
40	     * @throws MissingOwnerFieldsException if any of {@code firstName}, {@code lastName},
41	     *                                     {@code address}, {@code city} or {@code telephone}
42	     *                                     is {@code null} or blank
43	     */
44	    public static void validateRequiredFields(OwnerFieldsDto ownerFields) {
45	        List<String> missing = new ArrayList<>();
46	        addIfBlank(missing, "firstName", ownerFields.getFirstName());
47	        addIfBlank(missing, "lastName", ownerFields.getLastName());
48	        addIfBlank(missing, "address", ownerFields.getAddress());
49	        addIfBlank(missing, "city", ownerFields.getCity());
50	        addIfBlank(missing, "telephone", ownerFields.getTelephone());
51	        if (!missing.isEmpty()) {
52	            throw new MissingOwnerFieldsException(missing);
53	        }
54	    }
55	
56	    private static void addIfBlank(List<String> missing, String fieldName, String value) {
57	        if (value == null || value.isBlank()) {
58	            missing.add(fieldName);
59	        }
60	    }
61	}
