17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import org.springframework.samples.petclinic.service.ClinicService;
20	import org.springframework.stereotype.Component;
21	
22	/**
23	 * Enforces that an owner's normalized telephone is unique across all owners. Telephones are
24	 * compared in their canonical storage form (see {@link TelephoneNormalizer}), so two owners whose
25	 * submitted telephones differ only in formatting are still treated as duplicates.
26	 */
27	@Component
28	public class OwnerTelephoneUniquenessValidator {
29	
30	    private final ClinicService clinicService;
31	
32	    public OwnerTelephoneUniquenessValidator(ClinicService clinicService) {
33	        this.clinicService = clinicService;
34	    }
35	
36	    /**
37	     * Rejects a normalized telephone that is already used by any existing owner.
38	     *
39	     * @param normalizedTelephone the normalized telephone of the owner being created
40	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
41	     */
42	    public void validateUnique(String normalizedTelephone) {
43	        if (!this.clinicService.findOwnerByTelephone(normalizedTelephone).isEmpty()) {
44	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
45	        }
46	    }
47	}
