39	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
40	import org.springframework.samples.petclinic.rest.validation.OwnerFieldsValidator;
41	import org.springframework.samples.petclinic.rest.validation.OwnerTelephoneUniquenessValidator;
42	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
43	import org.springframework.samples.petclinic.service.ClinicService;
44	import org.springframework.security.access.prepost.PreAuthorize;
45	import org.springframework.web.bind.annotation.CrossOrigin;
46	import org.springframework.web.bind.annotation.RequestMapping;
47	import org.springframework.web.bind.annotation.RestController;
48	import org.springframework.web.util.UriComponentsBuilder;
49	
50	import jakarta.transaction.Transactional;
51	
52	/**
53	 * @author Vitaliy Fedoriv
54	 */
55	
56	@RestController
57	@CrossOrigin(exposedHeaders = "errors, content-type")
58	@RequestMapping("/api")
59	public class OwnerRestControllerV1 implements OwnersApi {
60	
61	    private final ClinicService clinicService;
62	
63	    private final OwnerMapper ownerMapper;
64	
65	    private final PetMapper petMapper;
66	
67	    private final VisitMapper visitMapper;
68	
69	    private final OwnerTelephoneUniquenessValidator telephoneUniquenessValidator;
70	
71	    public OwnerRestControllerV1(ClinicService clinicService,
72	                                 OwnerMapper ownerMapper,
73	                                 PetMapper petMapper,
74	                                 VisitMapper visitMapper,
75	                                 OwnerTelephoneUniquenessValidator telephoneUniquenessValidator) {
76	        this.clinicService = clinicService;
77	        this.ownerMapper = ownerMapper;
78	        this.petMapper = petMapper;
79	        this.visitMapper = visitMapper;
80	        this.telephoneUniquenessValidator = telephoneUniquenessValidator;
81	    }
82	
83	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
84	    @Override
85	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
86	        Collection<Owner> owners;
87	        if (lastName != null) {
88	            owners = this.clinicService.findOwnerByLastName(lastName);
89	        } else {
90	            owners = this.clinicService.findAllOwners();
91	        }
92	        if (owners.isEmpty()) {
93	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
94	        }
95	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
101	        Owner owner = this.clinicService.findOwnerById(ownerId);
102	        if (owner == null) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
111	        OwnerFieldsValidator.validateRequiredFields(ownerFieldsDto);
112	        HttpHeaders headers = new HttpHeaders();
113	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
114	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
115	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
116	        this.telephoneUniquenessValidator.validateUnique(owner.getTelephone());
117	        owner.setCustomerCode(CustomerCodeGenerator.generate(owner.getLastName(), this.clinicService.countOwners()));
118	        this.clinicService.saveOwner(owner);
119	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
120	        headers.setLocation(UriComponentsBuilder.newInstance()
121	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
122	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
123	    }
124	
125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
128	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
129	        if (currentOwner == null) {
130	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
131	        }
132	        currentOwner.setAddress(ownerFieldsDto.getAddress());
133	        currentOwner.setCity(ownerFieldsDto.getCity());
134	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
135	        currentOwner.setLastName(ownerFieldsDto.getLastName());
136	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
137	        this.clinicService.saveOwner(currentOwner);
138	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Transactional
143	    @Override
144	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
145	        Owner owner = this.clinicService.findOwnerById(ownerId);
146	        if (owner == null) {
147	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
148	        }
149	        this.clinicService.deleteOwner(owner);
150	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
151	    }
152	
153	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
154	    @Override
155	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
156	        Owner owner = this.clinicService.findOwnerById(ownerId);
157	        if (owner == null) {
158	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
159	        }
160	        HttpHeaders headers = new HttpHeaders();
161	        Pet pet = petMapper.toPet(petFieldsDto);
162	        owner.setId(ownerId);
163	        pet.setOwner(owner);
164	        pet.getType().setName(null);
165	        this.clinicService.savePet(pet);
166	        PetDto petDto = petMapper.toPetDto(pet);
167	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
168	            .buildAndExpand(pet.getId()).toUri());
169	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
170	    }
171	
172	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
173	    @Override
174	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
175	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
176	        if (currentOwner != null) {
177	            Pet currentPet = this.clinicService.findPetById(petId);
178	            if (currentPet != null) {
179	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
180	                currentPet.setName(petFieldsDto.getName());
181	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
182	                this.clinicService.savePet(currentPet);
183	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
184	            }
185	        }
186	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
187	    }
188	
189	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
190	    @Override
191	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
192	        HttpHeaders headers = new HttpHeaders();
193	        Visit visit = visitMapper.toVisit(visitFieldsDto);
194	        Pet pet = new Pet();
195	        pet.setId(petId);
196	        visit.setPet(pet);
197	        this.clinicService.saveVisit(visit);
198	        VisitDto visitDto = visitMapper.toVisitDto(visit);
199	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
200	            .buildAndExpand(visit.getId()).toUri());
201	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
202	    }
203	
204	
205	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
206	    @Override
207	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
208	        Owner owner = this.clinicService.findOwnerById(ownerId);
209	        if (owner != null) {
210	            Pet pet = owner.getPet(petId);
211	            if (pet != null) {
212	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
213	            }
214	        }
215	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
216	    }
217	}
