169	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
170	    }
171	
172	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
173	    @Override
174	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
175	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
176	        if (currentOwner != null) {
177	            Pet currentPet = this.clinicService.findPetById(petId);
178	            if (currentPet != null) {
179	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
180	                currentPet.setName(petFieldsDto.getName());
181	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
182	                this.clinicService.savePet(currentPet);
183	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
184	            }
185	        }
186	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
187	    }
