189	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
190	    @Override
191	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
192	        HttpHeaders headers = new HttpHeaders();
193	        Visit visit = visitMapper.toVisit(visitFieldsDto);
194	        Pet pet = new Pet();
195	        pet.setId(petId);
196	        visit.setPet(pet);
197	        this.clinicService.saveVisit(visit);
198	        VisitDto visitDto = visitMapper.toVisitDto(visit);
199	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
200	            .buildAndExpand(visit.getId()).toUri());
201	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
202	    }
203	
204	
205	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
206	    @Override
207	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
208	        Owner owner = this.clinicService.findOwnerById(ownerId);
209	        if (owner != null) {
210	            Pet pet = owner.getPet(petId);
211	            if (pet != null) {
212	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
213	            }
214	        }
215	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
216	    }
217	}
